// ── Time / date helpers ───────────────────────────────────────────────────────
function parseTime(str) {
  if (!str) return null;
  const [h, m] = str.split(':').map(Number);
  return h * 60 + m;
}
// computeLateStatus(checkIn, ctx?)
// ctx = { userId, date, rota } — optional; enables on-call grace period logic.
// If the user was on an evening/weekend on-call shift the PREVIOUS day they
// get a grace window before being counted late:
//   • Heidi (HEIDI_ONCALL_USER_ID): 130 min grace → threshold 11:10
//   • All other on-call engineers:   90 min grace → threshold 10:30
function computeLateStatus(checkIn, ctx) {
  const arr   = parseTime(checkIn);
  const start = parseTime(START_TIME);
  if (arr == null) return null;

  // ── Determine effective threshold ───────────────────────────────────────
  let thresholdMins = start; // default: 09:00 sharp
  let graceLabel    = null;

  if (ctx && ctx.userId && ctx.date && ctx.rota) {
    const { userId, date, rota } = ctx;
    // Check if prev calendar day had an overnight on-call shift for this user
    const prevDate    = addDays(date, -1);
    const prevShift   = (rota[userId] || {})[prevDate] || 'off';
    const wasOnCall   = ONCALL_OVERNIGHT_SHIFTS.includes(prevShift);

    if (wasOnCall) {
      const graceMins = userId === HEIDI_ONCALL_USER_ID
        ? HEIDI_ONCALL_GRACE_MINS
        : DEFAULT_ONCALL_GRACE_MINS;
      thresholdMins = start + graceMins;
      const h = Math.floor(thresholdMins / 60);
      const m = thresholdMins % 60;
      graceLabel = `${String(h).padStart(2,'0')}:${String(m).padStart(2,'0')}`;
    }
  }

  const diff = arr - thresholdMins;
  if (diff <= 0) {
    return {
      status: 'ontime',
      label: graceLabel ? `On Time (grace to ${graceLabel})` : 'On Time',
      color: '#22c55e',
      diff: arr - start,
      graceLabel,
    };
  }
  return {
    status: 'late',
    label: graceLabel ? `+${diff}m (after ${graceLabel} grace)` : `+${arr - start}m`,
    color: '#ef4444',
    diff: arr - start,
    graceLabel,
  };
}
function isWeekday(dateStr) {
  const d = new Date(dateStr + 'T12:00:00').getDay();
  return d >= 1 && d <= 5;
}
function isWeekend(dateStr) {
  const d = new Date(dateStr + 'T00:00:00').getDay();
  return d === 0 || d === 6;
}
function isBankHoliday(dateStr, bh) {
  return (bh || []).some(b => (b.date || b) === dateStr);
}
function isOnHoliday(dateStr, userId, holidays) {
  return (holidays || []).some(h =>
    h.userId === userId && h.status === 'approved' &&
    dateStr >= h.startDate && dateStr <= h.endDate
  );
}
function addDays(dateStr, n) {
  const d = new Date(dateStr + 'T12:00:00');
  d.setDate(d.getDate() + n);
  return d.toISOString().slice(0, 10);
}
function getWeekStart(dateStr) {
  const d   = new Date(dateStr + 'T12:00:00');
  const day = d.getDay();
  d.setDate(d.getDate() + (day === 0 ? -6 : 1 - day));
  return d.toISOString().slice(0, 10);
}
function getWeeksFrom(startDate, count = 14) {
  const ws = getWeekStart(startDate);
  return Array.from({ length: count }, (_, i) => addDays(ws, i * 7));
}
function getAllWeekdays(weekStart) {
  return Array.from({ length: 5 }, (_, i) => addDays(weekStart, i));
}
function fmtDate(d) {
  return new Date(d + 'T00:00:00').toLocaleDateString('en-GB', { weekday: 'short', day: 'numeric', month: 'short' });
}
function fmtHours(ci, co) {
  if (!ci || !co) return null;
  const [h1, m1] = ci.split(':').map(Number);
  const [h2, m2] = co.split(':').map(Number);
  let m = (h2 * 60 + m2) - (h1 * 60 + m1);
  if (m < 0) m += 1440;
  return `${Math.floor(m / 60)}h${m % 60 > 0 ? ` ${m % 60}m` : ''}`;
}
// London-timezone helpers (handles GMT/BST automatically)
function londonNow() {
  const now   = new Date();
  const parts = new Intl.DateTimeFormat('en-GB', {
    timeZone: 'Europe/London',
    year: 'numeric', month: '2-digit', day: '2-digit',
    hour: '2-digit', minute: '2-digit', second: '2-digit', hour12: false,
  }).formatToParts(now);
  const p = {};
  parts.forEach(({ type, value }) => { p[type] = value; });
  return new Date(`${p.year}-${p.month}-${p.day}T${p.hour === '24' ? '00' : p.hour}:${p.minute}:${p.second}`);
}
function londonTodayStr() {
  const parts = new Intl.DateTimeFormat('en-GB', {
    timeZone: 'Europe/London', year: 'numeric', month: '2-digit', day: '2-digit',
  }).formatToParts(new Date());
  const p = {};
  parts.forEach(({ type, value }) => { p[type] = value; });
  return `${p.year}-${p.month}-${p.day}`;
}
function londonTimeStr() {
  return new Intl.DateTimeFormat('en-GB', {
    timeZone: 'Europe/London', hour: '2-digit', minute: '2-digit', hour12: false,
  }).format(new Date());
}

// ── Local date string ─────────────────────────────────────────────────────────
// CRITICAL: d.toISOString() returns UTC which can be 1 day behind local time
// in timezones ahead of UTC (e.g. BST/UTC+1). Always use local date parts.
function localDateStr(d) {
  const yyyy = d.getFullYear();
  const mm   = String(d.getMonth() + 1).padStart(2, '0');
  const dd   = String(d.getDate()).padStart(2, '0');
  return `${yyyy}-${mm}-${dd}`;
}

// ── Week/month grid helpers ───────────────────────────────────────────────────
function getWeekDates(offset = 0) {
  const base = new Date();
  const dow  = (base.getDay() + 6) % 7;   // Monday = 0
  base.setDate(base.getDate() - dow + offset * 7);
  return Array.from({ length: 7 }, (_, i) => {
    const d = new Date(base);
    d.setDate(base.getDate() + i);
    return localDateStr(d);  // ← was d.toISOString().slice(0,10) — UTC shift bug
  });
}
function getMonthDates(year, month) {
  const first    = new Date(year, month, 1);
  const last     = new Date(year, month + 1, 0);
  const startDow = (first.getDay() + 6) % 7;
  const days     = [];
  for (let pre = startDow - 1; pre >= 0; pre--) {
    const d = new Date(first);
    d.setDate(1 - pre);
    days.push({ date: localDateStr(d), isCurrentMonth: false }); // ← UTC fix
  }
  for (let day = 1; day <= last.getDate(); day++)
    days.push({ date: localDateStr(new Date(year, month, day)), isCurrentMonth: true }); // ← UTC fix
  while (days.length % 7 !== 0) {
    const prev = new Date(days[days.length - 1].date + 'T12:00:00');
    prev.setDate(prev.getDate() + 1);
    days.push({ date: localDateStr(prev), isCurrentMonth: false }); // ← UTC fix
  }
  return days;
}

// ── Data normaliser (old obj format → new array format) ───────────────────────
function normaliseEntries(uid, data) {
  if (!data) return [];
  if (Array.isArray(data)) return data;
  // Old format: { [date]: { type, arrival, departure, note, confirmedBy, … } }
  return Object.entries(data).map(([date, v]) => {
    if (!v || typeof v !== 'object') return null;
    const checkIn  = v.checkIn  || v.arrival   || null;
    const checkOut = v.checkOut || v.departure  || null;
    let status = v.status;
    if (!status) {
      if (v.type === 'office') status = 'office';
      else status = v.type || 'office';
    }
    return {
      id:                 v.id || `ck-${uid}-${date}`,
      date,
      checkIn,
      checkOut,
      status:             normStatus(status),
      notes:              v.notes || v.note || '',
      confirmedByManager: !!(v.confirmedByManager || v.confirmedBy),
      confirmedAt:        v.confirmedAt || null,
      device:             v.device             || null,
      checkOutDevice:     v.checkOutDevice     || null,
    };
  }).filter(Boolean);
}

