// ── Mini bar chart ────────────────────────────────────────────────────────────
function MiniBar({ value, max, color, height = 36, width = 22, label }) {
  const pct = max > 0 ? Math.min(value / max, 1) : 0;
  return (
    <div style={{ display: 'flex', flexDirection: 'column', alignItems: 'center', gap: 2 }}>
      <div style={{ fontSize: 10, color: '#94a3b8', fontWeight: 600 }}>{label}</div>
      <div style={{ width, height, background: 'rgba(255,255,255,0.05)', borderRadius: 4,
        display: 'flex', alignItems: 'flex-end', overflow: 'hidden', border: '1px solid rgba(255,255,255,0.06)' }}>
        <div style={{ width: '100%', height: `${pct * 100}%`, background: color,
          borderRadius: '3px 3px 0 0', transition: 'height 0.4s ease' }} />
      </div>
      <div style={{ fontSize: 11, fontWeight: 700, color, fontFamily: 'DM Mono' }}>{value}</div>
    </div>
  );
}

// ── Donut chart ───────────────────────────────────────────────────────────────
function Donut({ pct, color, size = 64, label }) {
  const r    = (size - 10) / 2;
  const circ = 2 * Math.PI * r;
  const dash = circ * Math.min(pct / 100, 1);
  return (
    <div style={{ display: 'flex', flexDirection: 'column', alignItems: 'center', gap: 4 }}>
      <div style={{ position: 'relative', width: size, height: size }}>
        <svg width={size} height={size} style={{ transform: 'rotate(-90deg)' }}>
          <circle cx={size/2} cy={size/2} r={r} fill="none" stroke="rgba(255,255,255,0.06)" strokeWidth={6} />
          <circle cx={size/2} cy={size/2} r={r} fill="none" stroke={color} strokeWidth={6}
            strokeDasharray={`${dash} ${circ}`} strokeLinecap="round"
            style={{ transition: 'stroke-dasharray 0.5s ease' }} />
        </svg>
        <div style={{ position: 'absolute', inset: 0, display: 'flex', alignItems: 'center',
          justifyContent: 'center', fontSize: size < 70 ? 12 : 15, fontWeight: 700, color, fontFamily: 'DM Mono' }}>
          {Math.round(pct)}%
        </div>
      </div>
      {label && <div style={{ fontSize: 10, color: '#94a3b8', textAlign: 'center', maxWidth: size + 20 }}>{label}</div>}
    </div>
  );
}

// ── Heat map cell ─────────────────────────────────────────────────────────────
// lateCtx = { userId, date, rota } — optional; enables on-call grace
function HeatCell({ entry, bankHol, holiday, isToday, isFuture, lateCtx }) {
  let bg    = 'rgba(255,255,255,0.03)';
  let title = 'No data';
  if (holiday)       { bg = 'rgba(139,92,246,0.18)';  title = 'Holiday'; }
  else if (bankHol)  { bg = 'rgba(99,102,241,0.25)';  title = 'Bank Holiday'; }
  else if (isFuture) { bg = 'rgba(255,255,255,0.02)'; title = 'Future'; }
  else if (entry) {
    if (entry.status === 'office' || entry.status === 'wfh') {
      const ls = computeLateStatus(entry.checkIn, lateCtx);
      if (!ls || ls.status === 'ontime') { bg = 'rgba(34,197,94,0.28)'; title = `In: ${entry.checkIn || '?'}${ls?.graceLabel ? ` (grace to ${ls.graceLabel})` : ''}`; }
      else                               { bg = 'rgba(239,68,68,0.3)';  title = `Late: ${entry.checkIn}${ls?.graceLabel ? ` (after ${ls.graceLabel} grace)` : ''}`; }
    } else if (entry.status === 'late')   { bg = 'rgba(239,68,68,0.3)';   title = `Late: ${entry.checkIn || '?'}`; }
    else if (entry.status === 'wfh')    { bg = 'rgba(59,130,246,0.22)'; title = 'WFH'; }
    else if (entry.status === 'absent') { bg = 'rgba(239,68,68,0.15)'; title = 'Absent'; }
  }
  return (
    <div title={title} style={{
      width: 18, height: 18, borderRadius: 3, background: bg,
      border: isToday ? '1.5px solid #00c2ff' : '1px solid rgba(255,255,255,0.05)',
      cursor: 'pointer',
    }} />
  );
}

// ── WeekView sub-component ────────────────────────────────────────────────────
function WeekView({ entries, weekDates, bankHolidays = [], onLogDay }) {
  const today = londonTodayStr();
  const DAYS  = ['Mon', 'Tue', 'Wed', 'Thu', 'Fri', 'Sat', 'Sun'];
  return (
    <div style={{ overflowX: 'auto' }}>
      <table>
        <thead>
          <tr>
            {weekDates.map((d, i) => {
              const bh      = bankHolidays.find(b => (b.date || b) === d);
              const isToday = d === today;
              const isWE    = i >= 5;
              return (
                <th key={d} style={{ textAlign: 'center', fontSize: 11, minWidth: 100,
                  color: isToday ? 'var(--accent)' : bh ? '#fca5a5' : isWE ? '#818cf8' : undefined }}>
                  {DAYS[i]}<br />
                  <span style={{ fontFamily: 'DM Mono', fontSize: 10 }}>
                    {new Date(d + 'T00:00:00').getDate()} {bh ? '🔴' : ''}
                  </span>
                </th>
              );
            })}
          </tr>
        </thead>
        <tbody>
          <tr>
            {weekDates.map(d => {
              const entry   = entries.find(e => e.date === d);
              const isToday = d === today;
              const isBH    = bankHolidays.some(b => (b.date || b) === d);
              const isWE    = isWeekend(d);
              const hrs     = entry ? fmtHours(entry.checkIn, entry.checkOut) : null;
              const canLog  = onLogDay && !isBH;
              if (isBH) return (
                <td key={d} style={{ textAlign: 'center', background: 'rgba(127,29,29,0.15)' }}>
                  <div style={{ fontSize: 10, color: '#fca5a5' }}>Bank Holiday</div>
                </td>
              );
              return (
                <td key={d} style={{ textAlign: 'center', verticalAlign: 'top', padding: '10px 8px',
                  background: isToday ? 'rgba(59,130,246,0.07)' : isWE ? 'rgba(129,140,248,0.04)' : undefined,
                  cursor: canLog && !entry ? 'pointer' : undefined }}
                  onClick={() => canLog && !entry && onLogDay(d)}
                  title={canLog && !entry ? `Log entry for ${fmtDate(d)}` : undefined}>
                  {entry ? (
                    <div>
                      <StatusPill status={entry.status} small />
                      <div style={{ fontFamily: 'DM Mono', fontSize: 11, marginTop: 5, color: 'var(--text-secondary)' }}>
                        {entry.checkIn || '—'} → {entry.checkOut || '…'}
                      </div>
                      {hrs && <div style={{ fontSize: 10, color: '#6ee7b7', marginTop: 3 }}>{hrs}</div>}
                      {entry.confirmedByManager && <div style={{ fontSize: 9, color: '#10b981', marginTop: 3 }}>✓ Confirmed</div>}
                      {canLog && (
                        <button className="btn btn-secondary btn-sm" style={{ marginTop: 5, fontSize: 10, padding: '2px 6px' }}
                          onClick={e => { e.stopPropagation(); onLogDay(d, entry); }}>✏</button>
                      )}
                    </div>
                  ) : (
                    <div style={{ fontSize: 10, color: isWE ? 'var(--border)' : canLog ? '#475569' : 'var(--text-muted)' }}>
                      {isWE ? 'Weekend' : d <= today ? (canLog ? <span style={{ fontSize: 18, opacity: 0.3 }}>+</span> : '—') : ''}
                    </div>
                  )}
                </td>
              );
            })}
          </tr>
        </tbody>
      </table>
    </div>
  );
}

// ── MonthView sub-component ───────────────────────────────────────────────────
function MonthView({ entries, year, month, bankHolidays = [], onLogDay }) {
  const today = londonTodayStr();
  const days  = getMonthDates(year, month);
  const DAYS  = ['Mon', 'Tue', 'Wed', 'Thu', 'Fri', 'Sat', 'Sun'];
  return (
    <div>
      <div style={{ display: 'grid', gridTemplateColumns: 'repeat(7, 1fr)', gap: 1, marginBottom: 2 }}>
        {DAYS.map(d => (
          <div key={d} style={{ textAlign: 'center', fontSize: 10, fontWeight: 600,
            color: 'var(--text-muted)', padding: '4px 0' }}>{d}</div>
        ))}
      </div>
      <div style={{ display: 'grid', gridTemplateColumns: 'repeat(7, 1fr)', gap: 3 }}>
        {days.map(({ date, isCurrentMonth }) => {
          const entry   = entries.find(e => e.date === date);
          const isToday = date === today;
          const isBH    = bankHolidays.some(b => (b.date || b) === date);
          const isWE    = isWeekend(date);
          const s       = entry ? statusCfg(entry.status) : null;
          const hrs     = entry ? fmtHours(entry.checkIn, entry.checkOut) : null;
          const canLog  = onLogDay && isCurrentMonth && !isWE && !isBH && date <= today;
          return (
            <div key={date} onClick={() => canLog && !entry && onLogDay(date)}
              title={canLog && !entry ? `Log entry for ${fmtDate(date)}` : undefined}
              style={{
                minHeight: 64, borderRadius: 8, padding: '6px 7px',
                background: isBH ? 'rgba(127,29,29,0.2)' : isToday ? 'rgba(59,130,246,0.12)'
                  : isWE ? 'rgba(129,140,248,0.05)' : 'var(--bg-card2)',
                border: isToday ? '1.5px solid var(--accent)' : '1px solid var(--border)',
                opacity: isCurrentMonth ? 1 : 0.35,
                cursor: canLog && !entry ? 'pointer' : undefined,
                position: 'relative',
              }}>
              <div style={{ fontSize: 11, fontWeight: isToday ? 700 : 400, marginBottom: 3,
                color: isToday ? 'var(--accent)' : isBH ? '#fca5a5' : isWE ? '#818cf8' : 'var(--text-muted)' }}>
                {new Date(date + 'T00:00:00').getDate()}
                {isBH && <span style={{ fontSize: 8, marginLeft: 3 }}>BH</span>}
              </div>
              {entry && s && (
                <div>
                  <div style={{ fontSize: 9, fontWeight: 700, color: s.color, background: s.bg,
                    borderRadius: 4, padding: '1px 4px', display: 'inline-block', marginBottom: 2 }}>
                    {s.icon} {s.label}
                  </div>
                  <div style={{ fontSize: 9, color: 'var(--text-muted)', fontFamily: 'DM Mono' }}>
                    {entry.checkIn} {entry.checkOut ? `→ ${entry.checkOut}` : ''}
                  </div>
                  {hrs && <div style={{ fontSize: 8, color: '#6ee7b7' }}>{hrs}</div>}
                  {canLog && (
                    <button className="btn btn-secondary" onClick={e => { e.stopPropagation(); onLogDay(date, entry); }}
                      style={{ fontSize: 9, padding: '1px 5px', marginTop: 3, display: 'block' }}>✏</button>
                  )}
                </div>
              )}
              {!entry && date < today && isCurrentMonth && !isWE && !isBH && (
                <div style={{ fontSize: 9, color: canLog ? 'rgba(255,255,255,0.15)' : 'var(--border)',
                  position: 'absolute', bottom: 6, right: 7, fontSize: 16 }}>
                  {canLog ? '+' : '—'}
                </div>
              )}
            </div>
          );
        })}
      </div>
    </div>
  );
}

// ── Excel export (manager only) ───────────────────────────────────────────────
// The SheetJS (XLSX) library isn't loaded anywhere by default — it's fetched
// lazily, only when someone actually exports, so people who never use this
// feature don't pay for loading it. Cached as a promise so clicking export
// twice in a row (e.g. before the first load finishes) doesn't inject the
// CDN script a second time.
//
// NOTE: this loads "xlsx-js-style" rather than plain SheetJS. Standard
// SheetJS Community Edition can READ cell styles but can't WRITE them —
// colored fills/fonts on export are a Pro-only feature there. xlsx-js-style
// is a community fork that adds writable cell styling while keeping the
// exact same XLSX.* API, so nothing else about how it's called changes.
let _xlsxLoadPromise = null;
function loadXLSX() {
  if (window.XLSX && window.XLSX.__styled) return Promise.resolve(window.XLSX);
  if (_xlsxLoadPromise) return _xlsxLoadPromise;
  _xlsxLoadPromise = new Promise((resolve, reject) => {
    const s = document.createElement('script');
    s.src = 'https://cdn.jsdelivr.net/npm/xlsx-js-style@1.2.0/dist/xlsx.bundle.js';
    s.onload = () => {
      if (window.XLSX) { window.XLSX.__styled = true; resolve(window.XLSX); }
      else reject(new Error('SheetJS script loaded but window.XLSX is still missing.'));
    };
    s.onerror = () => {
      _xlsxLoadPromise = null; // allow a retry on the next export attempt
      reject(new Error('Could not load the SheetJS library from the CDN — check your network connection.'));
    };
    document.head.appendChild(s);
  });
  return _xlsxLoadPromise;
}

// ── Shared cell styles for every Excel export in this file ──────────────────
const XSTYLE = {
  header:   { font: { bold: true, color: { rgb: 'FFFFFF' } }, fill: { fgColor: { rgb: '1F2937' } }, alignment: { vertical: 'center', horizontal: 'center', wrapText: true }, border: allBorder('B8BFC7') },
  title:    { font: { bold: true, sz: 16, color: { rgb: '111827' } } },
  subtitle: { font: { italic: true, sz: 10, color: { rgb: '6B7280' } } },
  office:   { fill: { fgColor: { rgb: 'DCEAFB' } }, font: { color: { rgb: '1D4ED8' } }, border: allBorder('E2E8F0') },
  wfh:      { fill: { fgColor: { rgb: 'E4DCFB' } }, font: { color: { rgb: '6D28D9' } }, border: allBorder('E2E8F0') },
  absent:   { fill: { fgColor: { rgb: 'FBDCDC' } }, font: { color: { rgb: 'B91C1C' } }, border: allBorder('E2E8F0') },
  holiday:  { fill: { fgColor: { rgb: 'FDEFC7' } }, font: { color: { rgb: 'B45309' } }, border: allBorder('E2E8F0') },
  bankhol:  { fill: { fgColor: { rgb: 'E0F2E9' } }, font: { color: { rgb: '15803D' } }, border: allBorder('E2E8F0') },
  late:     { fill: { fgColor: { rgb: 'FBDCDC' } }, font: { bold: true, color: { rgb: 'B91C1C' } }, border: allBorder('E2E8F0') },
  ontime:   { fill: { fgColor: { rgb: 'DCFBE4' } }, font: { color: { rgb: '15803D' } }, border: allBorder('E2E8F0') },
  plain:    { border: allBorder('E2E8F0') },
  goodPct:  { fill: { fgColor: { rgb: 'DCFBE4' } }, font: { bold: true, color: { rgb: '15803D' } }, border: allBorder('E2E8F0') },
  badPct:   { fill: { fgColor: { rgb: 'FBDCDC' } }, font: { bold: true, color: { rgb: 'B91C1C' } }, border: allBorder('E2E8F0') },
};
function allBorder(rgb) {
  const side = { style: 'thin', color: { rgb } };
  return { top: side, bottom: side, left: side, right: side };
}
function styleCell(v, style) { return { v, s: style, t: typeof v === 'number' ? 'n' : 's' }; }
function statusStyle(status) {
  if (status === 'office')        return XSTYLE.office;
  if (status === 'wfh')           return XSTYLE.wfh;
  if (status === 'absent')        return XSTYLE.absent;
  if (status === 'Holiday')       return XSTYLE.holiday;
  if (status === 'Bank Holiday')  return XSTYLE.bankhol;
  return XSTYLE.plain;
}
// Safe Excel sheet name: max 31 chars, no : \ / ? * [ ]
function safeSheetName(name) {
  return (name || 'Sheet').replace(/[:\\/?*[\]]/g, ' ').slice(0, 31) || 'Sheet';
}

async function exportAttendanceExcel(users, timekeeping, bankHolidays, holidays, from, to, rota) {
  let XLSX;
  try {
    XLSX = await loadXLSX();
  } catch (e) {
    alert(`Couldn't load the Excel export library: ${e.message}`);
    return;
  }
  const bh  = (bankHolidays || []).map(b => b.date || b);
  const fmt = ds => new Date(ds + 'T12:00:00').toLocaleDateString('en-GB');
  const hdrs = ['Date', 'Day', 'Status', 'Check In', 'Check Out', 'Hours', 'Late Status', 'Late Reason', 'Notified MBA47', 'Check-In Device', 'Check-Out Device', 'Confirmed', 'Notes'];
  const colWidths = [12, 12, 14, 9, 10, 8, 12, 30, 14, 18, 18, 10, 30].map(w => ({ wch: w }));
  const wb = XLSX.utils.book_new();
  const engineerList = users || [];

  // ── Summary sheet first — quick per-engineer glance before the detail tabs
  const summaryHdrs = ['Engineer', 'Office Days', 'WFH Days', 'Absent Days', 'Late Arrivals', 'Total Entries'];
  const summaryRows = engineerList.map(u => {
    const entries = normaliseEntries(u.id, (timekeeping || {})[u.id])
      .filter(e => e.date && (!from || e.date >= from) && (!to || e.date <= to));
    const office = entries.filter(e => e.status === 'office').length;
    const wfh    = entries.filter(e => e.status === 'wfh').length;
    const absent = entries.filter(e => e.status === 'absent').length;
    const late   = entries.filter(e => e.checkIn && computeLateStatus(e.checkIn, { userId: u.id, date: e.date, rota: rota || {} })?.status === 'late').length;
    return [u.name, office, wfh, absent, late, entries.length];
  });
  const summaryAoA = [
    summaryHdrs.map(h => styleCell(h, XSTYLE.header)),
    ...summaryRows.map(r => r.map((v, i) => styleCell(v, i === 4 && v > 0 ? XSTYLE.late : XSTYLE.plain))),
  ];
  const summaryWs = XLSX.utils.aoa_to_sheet(summaryAoA);
  summaryWs['!cols'] = [22, 12, 10, 12, 13, 12].map(w => ({ wch: w }));
  XLSX.utils.book_append_sheet(wb, summaryWs, 'Summary');

  // ── One sheet per engineer ─────────────────────────────────────────────
  engineerList.forEach(u => {
    const entries = normaliseEntries(u.id, (timekeeping || {})[u.id])
      .filter(e => e.date && (!from || e.date >= from) && (!to || e.date <= to))
      .sort((a, b) => (a.date || '').localeCompare(b.date || ''));
    const rows = entries.map(e => {
      const day  = new Date(e.date + 'T12:00:00').toLocaleDateString('en-GB', { weekday: 'long' });
      const isBH = isBankHoliday(e.date, bh);
      const isH  = isOnHoliday(e.date, u.id, holidays);
      const ls   = e.checkIn ? computeLateStatus(e.checkIn, { userId: u.id, date: e.date, rota: rota || {} }) : null;
      const hrs  = fmtHours(e.checkIn, e.checkOut) || '';
      const statusLabel = isBH ? 'Bank Holiday' : isH ? 'Holiday' : (e.status || '—');
      const lateLabel = ls ? ls.label : (e.status === 'wfh' ? 'WFH' : e.status === 'absent' ? 'Absent' : '—');
      const sStyle = statusStyle(statusLabel === 'Holiday' || statusLabel === 'Bank Holiday' ? statusLabel : e.status);
      return [
        styleCell(fmt(e.date), XSTYLE.plain),
        styleCell(day, XSTYLE.plain),
        styleCell(statusLabel, sStyle),
        styleCell(e.checkIn || '—', XSTYLE.plain),
        styleCell(e.checkOut || '—', XSTYLE.plain),
        styleCell(hrs, XSTYLE.plain),
        styleCell(lateLabel, ls?.status === 'late' ? XSTYLE.late : ls?.status === 'ontime' ? XSTYLE.ontime : XSTYLE.plain),
        styleCell(e.lateReason || (ls?.status === 'late' ? '⚠ No reason given' : '—'), ls?.status === 'late' && !e.lateReason ? XSTYLE.late : XSTYLE.plain),
        styleCell(e.lateNotifiedManager ? '✓ Yes' : (ls?.status === 'late' ? '✗ No' : '—'), e.lateNotifiedManager ? XSTYLE.ontime : (ls?.status === 'late' ? XSTYLE.late : XSTYLE.plain)),
        styleCell(e.device ? (DEVICE_META[e.device]?.label || e.device) : '—', XSTYLE.plain),
        styleCell(e.checkOutDevice ? (DEVICE_META[e.checkOutDevice]?.label || e.checkOutDevice) : '—', XSTYLE.plain),
        styleCell(e.confirmedByManager ? '✓' : '—', XSTYLE.plain),
        styleCell(e.notes || '', XSTYLE.plain),
      ];
    });
    const aoa = [
      [styleCell(u.name, XSTYLE.title)],
      [styleCell(`${from || 'All time'} → ${to || 'now'}`, XSTYLE.subtitle)],
      [],
      hdrs.map(h => styleCell(h, XSTYLE.header)),
      ...rows,
    ];
    const ws = XLSX.utils.aoa_to_sheet(aoa);
    ws['!cols'] = colWidths;
    ws['!merges'] = [{ s: { r: 0, c: 0 }, e: { r: 0, c: hdrs.length - 1 } }, { s: { r: 1, c: 0 }, e: { r: 1, c: hdrs.length - 1 } }];
    XLSX.utils.book_append_sheet(wb, ws, safeSheetName(u.name));
  });

  XLSX.writeFile(wb, `CloudOps-Attendance-${(from || 'all').replace(/-/g, '')}-${(to || 'now').replace(/-/g, '')}.xlsx`);
}

// ── Word (.docx) — lazy-loaded the same way as XLSX ──────────────────────────
let _docxLoadPromise = null;
function loadDocx() {
  if (window.docx) return Promise.resolve(window.docx);
  if (_docxLoadPromise) return _docxLoadPromise;
  _docxLoadPromise = new Promise((resolve, reject) => {
    const s = document.createElement('script');
    s.src = 'https://cdn.jsdelivr.net/npm/docx@8.5.0/build/index.umd.min.js';
    s.onload = () => {
      if (window.docx) resolve(window.docx);
      else reject(new Error('docx script loaded but window.docx is still missing.'));
    };
    s.onerror = () => {
      _docxLoadPromise = null;
      reject(new Error('Could not load the Word export library from the CDN — check your network connection.'));
    };
    document.head.appendChild(s);
  });
  return _docxLoadPromise;
}

function downloadBlob(blob, filename) {
  const url = URL.createObjectURL(blob);
  const a = document.createElement('a');
  a.href = url; a.download = filename; a.click();
  URL.revokeObjectURL(url);
}

